mapper.select:
SELECT COUNT(*) FROM asset_snapshot
WHERE user_id = #{userId}
  AND snapshot_date = #{snapshotDate}
  AND category = #{category}
  AND is_latest = true

mapper.update:
UPDATE asset_snapshot
SET is_latest = false
WHERE user_id = #{userId}
  AND snapshot_date = #{snapshotDate}

mapper.select:
SELECT * FROM asset_snapshot
WHERE user_id = #{userId}
  AND snapshot_date < #{beforeDate}
ORDER BY snapshot_date DESC
LIMIT 1

SELECT * FROM asset_snapshot
WHERE user_id = #{userId}
  AND snapshot_date = #{snapshotDate}
  AND is_latest = true
ORDER BY category

SELECT MAX(snapshot_date) FROM asset_snapshot
WHERE user_id = #{userId}
  AND is_latest = true

SELECT DISTINCT snapshot_date FROM asset_snapshot
WHERE user_id = #{userId}
  AND is_latest = true
   AND snapshot_date >= #{from} 
   AND snapshot_date <= #{to} 
ORDER BY snapshot_date DESC
